    impl<T> Deref for ReentrantMutexGuard<'_, T> {
        type Target = T;

        #[inline(always)]
        fn deref(&self) -> &Self::Target {
            self.0
        }
    }

    pub(crate) struct ArcReentrantMutexGuard<T>(XRc<ReentrantMutex<T>>);

    impl<T> Deref for ArcReentrantMutexGuard<T> {
        type Target = T;

        #[inline(always)]
        fn deref(&self) -> &Self::Target {
            &self.0 .0
        }
    }
}

